-- Android credentials are fresh V2 identity bindings and never desktop owner grants
CREATE TABLE android_device_guard (id BIGINT PRIMARY KEY CHECK(id=1), observed_at BIGINT NOT NULL);
INSERT INTO android_device_guard(id,observed_at) VALUES(1,0);
CREATE TABLE android_passkeys (id TEXT PRIMARY KEY, identity_id TEXT NOT NULL REFERENCES identity_subjects(id), credential_id TEXT NOT NULL UNIQUE, label TEXT NOT NULL, credential TEXT NOT NULL, revision BIGINT NOT NULL, created_at BIGINT NOT NULL, last_used_at BIGINT);
CREATE TABLE android_passkey_challenges (id TEXT PRIMARY KEY, identity_id TEXT NOT NULL REFERENCES identity_subjects(id), identity_revision BIGINT NOT NULL, kind TEXT NOT NULL, actor_session_id TEXT, actor_session_revision BIGINT, device_id TEXT, state TEXT NOT NULL, binding TEXT NOT NULL, expires_at BIGINT NOT NULL, consumed BIGINT NOT NULL CHECK(consumed IN(0,1)));
CREATE TABLE android_push_subscriptions (id TEXT PRIMARY KEY, identity_id TEXT NOT NULL REFERENCES identity_subjects(id), organization_id TEXT, device_id TEXT NOT NULL, token_sha256 TEXT NOT NULL UNIQUE, sealed_token TEXT NOT NULL, revision BIGINT NOT NULL, created_at BIGINT NOT NULL, last_success_at BIGINT, active BIGINT NOT NULL CHECK(active IN(0,1)), UNIQUE(identity_id,device_id));
CREATE TABLE android_push_outbox (id TEXT PRIMARY KEY, identity_id TEXT NOT NULL REFERENCES identity_subjects(id), subscription_id TEXT NOT NULL REFERENCES android_push_subscriptions(id), subscription_revision BIGINT NOT NULL, team_id TEXT, project_id TEXT, run_id TEXT, event_key TEXT NOT NULL, payload TEXT NOT NULL, state TEXT NOT NULL, observed_at BIGINT NOT NULL, error_code TEXT, UNIQUE(subscription_id,event_key));
CREATE TABLE android_devices (id TEXT PRIMARY KEY, identity_id TEXT NOT NULL REFERENCES identity_subjects(id), team_id TEXT REFERENCES identity_organizations(id), registration TEXT NOT NULL, pairing_request_sha256 TEXT NOT NULL, revision BIGINT NOT NULL, execution_revision BIGINT NOT NULL, draining BIGINT NOT NULL CHECK(draining IN(0,1)), revoked BIGINT NOT NULL CHECK(revoked IN(0,1)), last_seen_at BIGINT NOT NULL);
CREATE TABLE android_device_credentials (id TEXT PRIMARY KEY, executor_id TEXT NOT NULL REFERENCES android_devices(id), identity_id TEXT NOT NULL REFERENCES identity_subjects(id), token_sha256 TEXT NOT NULL UNIQUE, label TEXT NOT NULL, revision BIGINT NOT NULL, expires_at BIGINT NOT NULL, revoked BIGINT NOT NULL CHECK(revoked IN(0,1)));
CREATE TABLE android_device_runs (id TEXT PRIMARY KEY, team_id TEXT NOT NULL REFERENCES identity_organizations(id), project_id TEXT NOT NULL REFERENCES tenant_projects(id), order_id TEXT NOT NULL REFERENCES team_orders(id), creator_id TEXT NOT NULL REFERENCES identity_subjects(id), creator_session_id TEXT NOT NULL REFERENCES identity_sessions(id), creator_session_revision BIGINT NOT NULL, authorization_epoch BIGINT NOT NULL, project_revision BIGINT NOT NULL, executor_id TEXT NOT NULL REFERENCES android_devices(id), executor_revision BIGINT NOT NULL, creation_key TEXT NOT NULL, request_sha256 TEXT NOT NULL, payload TEXT NOT NULL, state TEXT NOT NULL, revision BIGINT NOT NULL, lease_token TEXT, credential_id TEXT, credential_revision BIGINT, lease_expires_at BIGINT, completion_sha256 TEXT, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, UNIQUE(creator_id,creation_key));
CREATE TABLE android_device_events (run_id TEXT NOT NULL REFERENCES android_device_runs(id), sequence BIGINT NOT NULL, event_id TEXT NOT NULL UNIQUE, source_event_id TEXT, request_sha256 TEXT NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(run_id,sequence), UNIQUE(run_id,source_event_id));
CREATE TABLE android_device_artifacts (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES android_device_runs(id), payload TEXT NOT NULL, bytes_base64 TEXT NOT NULL);
CREATE TABLE android_desktop_sessions (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES android_device_runs(id), executor_id TEXT NOT NULL REFERENCES android_devices(id), credential_id TEXT NOT NULL REFERENCES android_device_credentials(id), credential_revision BIGINT NOT NULL, lease_token TEXT NOT NULL, revision BIGINT NOT NULL, state TEXT NOT NULL, payload TEXT NOT NULL, controller_generation TEXT, created_at BIGINT NOT NULL, ended_at BIGINT);
CREATE TABLE android_device_tickets (token_sha256 TEXT PRIMARY KEY, identity_id TEXT NOT NULL REFERENCES identity_subjects(id), session_id TEXT NOT NULL REFERENCES identity_sessions(id), session_revision BIGINT NOT NULL, kind TEXT NOT NULL, run_id TEXT, desktop_id TEXT, payload TEXT NOT NULL, expires_at BIGINT NOT NULL, consumed BIGINT NOT NULL CHECK(consumed IN(0,1)));
CREATE TABLE android_device_snapshots (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES android_device_runs(id), payload TEXT NOT NULL, committed BIGINT NOT NULL CHECK(committed IN(0,1)));
CREATE TABLE android_device_snapshot_chunks (manifest_id TEXT NOT NULL REFERENCES android_device_snapshots(id), digest TEXT NOT NULL, bytes_base64 TEXT NOT NULL, PRIMARY KEY(manifest_id,digest));
CREATE TABLE android_device_requests (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES android_device_runs(id), kind TEXT NOT NULL, source_id TEXT, request_sha256 TEXT NOT NULL, payload TEXT NOT NULL, state TEXT NOT NULL, revision BIGINT NOT NULL, expires_at BIGINT NOT NULL, UNIQUE(run_id,kind,source_id));
CREATE TABLE android_device_checkpoints (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES android_device_runs(id), source_id TEXT NOT NULL, request_sha256 TEXT NOT NULL, payload TEXT NOT NULL, UNIQUE(run_id,source_id));
CREATE TABLE android_fleet_nonces (nonce_sha256 TEXT PRIMARY KEY, identity_id TEXT NOT NULL REFERENCES identity_subjects(id), organization_id TEXT NOT NULL REFERENCES identity_organizations(id), expires_at BIGINT NOT NULL);
